import { createHash } from 'node:crypto';
import { describe, expect, it } from 'vitest';
import classic from '../../src/lib/params/classic.json';
import { createNoopJsCallback } from '../../src/lib/wasm/callbacks';
import { loadMicropolisMainModule } from '../../src/lib/wasm/node';
import type { MainModule, Micropolis } from '../../src/types/micropolisengine.d.js';

type Center = [number, number];

// This repository has no tags. The pinned values were generated by the
// tracked HEAD's original doPowerScan traversal (the pre-experiment code),
// with the same seed, city, demolition order, and tick count.

function powerPlantCenters(engine: MainModule, sim: Micropolis): Center[] {
	const tiles = new Uint16Array(engine.wasmMemory.buffer, sim.getMapAddress(), sim.getMapSize() / Uint16Array.BYTES_PER_ELEMENT);
	const zoneBit = engine.MapTileBits.ZONEBIT.value;
	const mask = engine.MapTileBits.LOMASK.value;
	const powerPlant = engine.Tiles.POWERPLANT.value;
	const nuclear = engine.Tiles.NUCLEAR.value;
	const solar = engine.Tiles.SOLARPOWER.value;
	const centers: Center[] = [];
	for (let x = 0; x < engine.WORLD_W; x += 1) {
		for (let y = 0; y < engine.WORLD_H; y += 1) {
			const tile = tiles[x * engine.WORLD_H + y] ?? 0;
			const value = tile & mask;
			if ((tile & zoneBit) !== 0 && (value === powerPlant || value === nuclear || value === solar)) centers.push([x, y]);
		}
	}
	return centers;
}

async function runClassicWithTwoPlantsRemoved(): Promise<{ mapSha1: string; resPop: number; unpoweredZoneCount: number }> {
	const engine = await loadMicropolisMainModule();
	const sim = new engine.Micropolis();
	const callback = createNoopJsCallback(engine);
	sim.setFixedSeed(42);
	sim.setCallback(callback, {});
	sim.init();
	try {
		for (const [name, value] of Object.entries(classic)) expect(sim.setParam(name, value)).toBe(true);
		sim.setEnableDisasters(false);
		expect(sim.loadCity('/cities/haight.cty')).toBe(true);
		const plants = powerPlantCenters(engine, sim);
		expect(plants.length).toBeGreaterThanOrEqual(2);
		for (const [x, y] of plants.slice(0, 2)) {
			const result = sim.doTool(engine.EditingTool.TOOL_BULLDOZER, x, y);
			expect(result.value).toBe(engine.ToolResult.TOOLRESULT_OK.value);
		}
		sim.setSpeed(3);
		sim.setPasses(1);
		for (let tick = 0; tick < 20_000; tick += 1) sim.simTick();
		const mapBytes = new Uint8Array(engine.wasmMemory.buffer, sim.getMapAddress(), sim.getMapSize());
		return {
			mapSha1: createHash('sha1').update(mapBytes).digest('hex'),
			resPop: sim.resPop,
			unpoweredZoneCount: sim.unpoweredZoneCount,
		};
	} finally {
		sim.delete();
	}
}

describe('Classic power compatibility against pre-change traversal', () => {
	it('matches the Haight two-plant outage reference after 20000 ticks', async () => {
		const result = await runClassicWithTwoPlantsRemoved();
		expect(result).toEqual({
			mapSha1: '031358d21ca69ea3a23bfb9010264c0fd9de3642',
			resPop: 3717,
			unpoweredZoneCount: 66,
		});
	});
});
